static void config_validate_solar_open2_model(const ds4_model *m) {
    g_ds4_shape = DS4_SHAPE_SOLAR_OPEN2_250B;
    memset(g_ds4_compress_ratios, 0, sizeof(g_ds4_compress_ratios));

    const uint32_t n_layer = required_u32(m, "solar-open2.block_count");
    const uint64_t n_ctx = required_u64_compat(m, "solar-open2.context_length");
    const uint32_t n_embd = required_u32(m, "solar-open2.embedding_length");
    const uint32_t n_vocab = required_u32(m, "solar-open2.vocab_size");
    const uint32_t n_ff_dense = required_u32(m, "solar-open2.feed_forward_length");
    const uint32_t n_head = required_u32(m, "solar-open2.attention.head_count");
    const uint32_t n_head_dim = required_u32(m, "solar-open2.attention.key_length");
    const uint32_t n_value_dim = required_u32(m, "solar-open2.attention.value_length");
    const uint32_t n_expert = required_u32(m, "solar-open2.expert_count");
    const uint32_t n_expert_used = required_u32(m, "solar-open2.expert_used_count");
    const uint32_t n_ff_exp = required_u32(m, "solar-open2.expert_feed_forward_length");
    const uint32_t n_expert_shared = required_u32(m, "solar-open2.expert_shared_count");
    const uint32_t n_leading_dense = required_u32(m, "solar-open2.leading_dense_block_count");
    const uint32_t n_ssm_conv = required_u32(m, "solar-open2.ssm.conv_kernel");
    const uint32_t n_kda_head_dim = required_u32(m, "solar-open2.kda.head_dim");
    const uint32_t expert_gating_func = required_u32(m, "solar-open2.expert_gating_func");

    config_expect_u32("block_count", n_layer, DS4_N_LAYER);
    config_expect_u64("context_length", n_ctx, DS4_ROPE_ORIG_CTX);
    config_expect_u32("embedding_length", n_embd, DS4_N_EMBD);
    config_expect_u32("vocab_size", n_vocab, DS4_N_VOCAB);
    config_expect_u32("feed_forward_length", n_ff_dense, DS4_N_FF_DENSE);
    config_expect_u32("attention.head_count", n_head, DS4_N_HEAD);
    config_expect_u32("attention.key_length", n_head_dim, DS4_N_HEAD_DIM);
    config_expect_u32("attention.value_length", n_value_dim, DS4_N_VALUE_DIM);
    config_expect_u32("expert_count", n_expert, DS4_N_EXPERT);
    config_expect_u32("expert_used_count", n_expert_used, DS4_N_EXPERT_USED);
    config_expect_u32("expert_feed_forward_length", n_ff_exp, DS4_N_FF_EXP);
    config_expect_u32("expert_shared_count", n_expert_shared, DS4_N_EXPERT_SHARED);
    config_expect_u32("leading_dense_block_count", n_leading_dense, 0);
    config_expect_u32("ssm.conv_kernel", n_ssm_conv, DS4_N_SSM_CONV);
    config_expect_u32("kda.head_dim", n_kda_head_dim, DS4_N_KDA_HEAD_DIM);
    config_expect_u32("expert_gating_func", expert_gating_func, 2);

    const float rms_eps = required_f32(
        m, "solar-open2.attention.layer_norm_rms_epsilon");
    config_expect_f32("attention.layer_norm_rms_epsilon", rms_eps, DS4_RMS_EPS);
    const float expert_weight_scale = required_f32(
        m, "solar-open2.expert_weights_scale");
    config_expect_f32("expert_weights_scale", expert_weight_scale,
                      DS4_EXPERT_WEIGHT_SCALE);
    const bool expert_weight_norm = required_bool(
        m, "solar-open2.expert_weights_norm");
    config_expect_bool("expert_weights_norm", expert_weight_norm, true);

    /* The converter retains rope.freq_base for HF compatibility, but Solar's
     * attention is NoPE.  Reject a non-zero dimension_count if one appears. */
    const float rope_freq_base = required_f32(m, "solar-open2.rope.freq_base");
    config_expect_f32("rope.freq_base (vestigial)", rope_freq_base,
                      DS4_ROPE_FREQ_BASE);
    uint32_t rope_dim = 0;
    if (model_get_u32(m, "solar-open2.rope.dimension_count", &rope_dim)) {
        config_expect_u32("rope.dimension_count (NoPE)", rope_dim, 0);
    }
    config_expect_bool("internal use_rope", DS4_USE_ROPE, false);

    const char *schedule_key = "solar-open2.attention.head_count_kv";
    ds4_array_ref schedule_arr;
    if (!model_get_array(m, schedule_key, &schedule_arr) ||
        (schedule_arr.type != GGUF_VALUE_INT32 &&
         schedule_arr.type != GGUF_VALUE_UINT32)) {
        fprintf(stderr,
                "ds4: required integer array metadata key is missing: %s\n",
                schedule_key);
        exit(1);
    }
    if (schedule_arr.len != n_layer) {
        fprintf(stderr, "ds4: %s has %" PRIu64 " entries, expected %u\n",
                schedule_key, schedule_arr.len, n_layer);
        exit(1);
    }

    ds4_cursor schedule = cursor_at(m, schedule_arr.data_pos);
    for (uint32_t il = 0; il < n_layer; il++) {
        uint32_t got = 0;
        if (schedule_arr.type == GGUF_VALUE_UINT32) {
            if (!cursor_u32(&schedule, &got)) ds4_die(schedule.error);
        } else {
            int32_t signed_got = 0;
            if (!cursor_read(&schedule, &signed_got, sizeof(signed_got))) {
                ds4_die(schedule.error);
            }
            if (signed_got < 0) {
                fprintf(stderr, "ds4: %s[%u] is negative: %d\n",
                        schedule_key, il, signed_got);
                exit(1);
            }
            got = (uint32_t)signed_got;
        }
        const uint32_t want = ds4_solar_layer_is_gqa(il) ? DS4_N_HEAD_KV : 0u;
        if (got != want) {
            fprintf(stderr,
                    "ds4: %s[%u]=%u, expected %u for the S-L-L-L schedule\n",
                    schedule_key, il, got, want);
            exit(1);
        }
    }

    config_expect_f32("internal KDA q/k l2 epsilon", DS4_KDA_L2_EPS,
                      1.0e-6f);
    config_expect_f32("internal KDA gate clamp minimum",
                      DS4_KDA_GATE_CLAMP_MIN, -5.0f);
}

/* K-EXAONE carries no MLA, indexer or hyper-connection metadata, so this reads
 * a strictly smaller key set than the DeepSeek4/GLM validators. The keys it
 * does read are the standard llama.cpp ones under the exaone-moe. prefix.
 *
 * The sliding-window schedule arrives as a per-layer bool array rather than a
 * scalar period, so it is checked element by element against LLLG: layer il is
 * full attention iff (il % 4) == 3. Silently accepting a different schedule
 * would put every fourth layer's KV cache on the wrong policy, which no output
 * check would catch until long contexts. */
static void config_validate_exaone_moe_model(const ds4_model *m) {
    g_ds4_shape = DS4_SHAPE_KEXAONE_236B;
    memset(g_ds4_compress_ratios, 0, sizeof(g_ds4_compress_ratios));

    const uint32_t n_layer = required_u32(m, "exaone-moe.block_count");
    const uint64_t n_ctx = required_u64_compat(m, "exaone-moe.context_length");
    const uint32_t n_embd = required_u32(m, "exaone-moe.embedding_length");
    const uint32_t n_vocab = required_u32(m, "exaone-moe.vocab_size");
    const uint32_t n_ff_dense = required_u32(m, "exaone-moe.feed_forward_length");
    const uint32_t n_head = required_u32(m, "exaone-moe.attention.head_count");
    const uint32_t n_head_kv = required_u32(m, "exaone-moe.attention.head_count_kv");
    const uint32_t n_head_dim = required_u32(m, "exaone-moe.attention.key_length");
    const uint32_t n_value_dim = required_u32(m, "exaone-moe.attention.value_length");
    const uint32_t n_expert = required_u32(m, "exaone-moe.expert_count");
    const uint32_t n_expert_used = required_u32(m, "exaone-moe.expert_used_count");
    const uint32_t n_ff_exp = required_u32(m, "exaone-moe.expert_feed_forward_length");
    const uint32_t n_ff_shexp = required_u32(m, "exaone-moe.expert_shared_feed_forward_length");
    const uint32_t n_expert_shared = required_u32(m, "exaone-moe.expert_shared_count");
    const uint32_t n_expert_group = required_u32(m, "exaone-moe.expert_group_count");
    const uint32_t n_expert_group_used = required_u32(m, "exaone-moe.expert_group_used_count");
    const uint32_t expert_gating_func = required_u32(m, "exaone-moe.expert_gating_func");
    const uint32_t n_leading_dense = required_u32(m, "exaone-moe.leading_dense_block_count");
    const uint32_t n_nextn = required_u32(m, "exaone-moe.nextn_predict_layers");
    const uint32_t n_swa = required_u32(m, "exaone-moe.attention.sliding_window");

    config_expect_u32("block_count", n_layer, DS4_N_LAYER);
    config_expect_u64("context_length", n_ctx, DS4_ROPE_ORIG_CTX);
    config_expect_u32("embedding_length", n_embd, DS4_N_EMBD);
    config_expect_u32("vocab_size", n_vocab, DS4_N_VOCAB);
    config_expect_u32("feed_forward_length", n_ff_dense, DS4_N_FF_DENSE);
    config_expect_u32("attention.head_count", n_head, DS4_N_HEAD);
    config_expect_u32("attention.head_count_kv", n_head_kv, DS4_N_HEAD_KV);
    config_expect_u32("attention.key_length", n_head_dim, DS4_N_HEAD_DIM);
    config_expect_u32("attention.value_length", n_value_dim, DS4_N_VALUE_DIM);
    config_expect_u32("expert_count", n_expert, DS4_N_EXPERT);
    config_expect_u32("expert_used_count", n_expert_used, DS4_N_EXPERT_USED);
    config_expect_u32("expert_feed_forward_length", n_ff_exp, DS4_N_FF_EXP);
    config_expect_u32("expert_shared_feed_forward_length", n_ff_shexp, DS4_N_FF_SHEXP);
    config_expect_u32("expert_shared_count", n_expert_shared, DS4_N_EXPERT_SHARED);
    config_expect_u32("expert_group_count", n_expert_group, 1);
    config_expect_u32("expert_group_used_count", n_expert_group_used, 1);
    config_expect_u32("expert_gating_func", expert_gating_func, 2); /* 2 = sigmoid */
    config_expect_u32("leading_dense_block_count", n_leading_dense, DS4_N_LEADING_DENSE);
    config_expect_u32("nextn_predict_layers", n_nextn, DS4_N_NEXTN_PREDICT);
    config_expect_u32("attention.sliding_window", n_swa, DS4_N_SWA);

    const float rope_freq_base = required_f32(m, "exaone-moe.rope.freq_base");
    config_expect_f32("rope.freq_base", rope_freq_base, DS4_ROPE_FREQ_BASE);
    const float rms_eps = required_f32(m, "exaone-moe.attention.layer_norm_rms_epsilon");
    config_expect_f32("attention.layer_norm_rms_epsilon", rms_eps, DS4_RMS_EPS);
    const float expert_weight_scale = required_f32(m, "exaone-moe.expert_weights_scale");
    config_expect_f32("expert_weights_scale", expert_weight_scale, DS4_EXPERT_WEIGHT_SCALE);
    const bool expert_weight_norm = required_bool(m, "exaone-moe.expert_weights_norm");
    config_expect_bool("expert_weights_norm", expert_weight_norm, true);

    /* sliding_window_pattern: one bool per block, true = sliding attention. */
    const char *swa_key = "exaone-moe.attention.sliding_window_pattern";
    ds4_array_ref arr;
    if (!model_get_array(m, swa_key, &arr) || arr.type != GGUF_VALUE_BOOL) {
        fprintf(stderr, "ds4: required bool array metadata key is missing: %s\n", swa_key);
        exit(1);
    }
    if (arr.len != n_layer) {
        fprintf(stderr, "ds4: %s has %llu entries, expected %u\n",
                swa_key, (unsigned long long)arr.len, n_layer);
        exit(1);
    }
    ds4_cursor swa_c = cursor_at(m, arr.data_pos);
    for (uint32_t il = 0; il < n_layer; il++) {
        uint8_t got = 0;
        if (!cursor_read(&swa_c, &got, sizeof(got))) ds4_die(swa_c.error);
        const bool want = ((il % DS4_N_SWA_PERIOD) != DS4_N_SWA_PERIOD - 1);
        if ((got != 0) != want) {
            fprintf(stderr,
                    "ds4: %s[%u] = %d, expected %d (LLLG: full attention on "
                    "every %u-th layer)\n",
                    swa_key, il, (int)(got != 0), (int)want, DS4_N_SWA_PERIOD);
            exit(1);
        }
    }
}

/* The first SSD-PLE artifact deliberately removes all 128 BF16 embedding
 * tables from the GGUF resident-weight set. Treat that as a strict storage
 * contract, not an optional hint: a runtime that ignores these fields must
 * fail during model validation instead of silently attempting an incomplete
 * resident model. */
static bool config_validate_qwen4exp_external_ple(const ds4_model *m) {
    ds4_str quantization = {0};
    ds4_str value = {0};
    const bool named_external =
        model_get_string(m, "general.quantization", &quantization) &&
        qwen4exp_ssd_precision_types(
            quantization, NULL, NULL, NULL, NULL);
    const bool declares_external =
        model_find_kv(m, "qwen4exp.ple.weight_storage") != NULL;

    if (named_external != declares_external) {
        ds4_die("Qwen4Exp SSD-PLE variant and external PLE metadata disagree");
    }
    if (!named_external) return false;

    if (!model_get_string(m, "qwen4exp.ple.weight_storage", &value) ||
        !ds4_streq(value, "ssd_backed_bounded_page_cache"))
        ds4_die("Qwen4Exp SSD-PLE requires bounded SSD-backed PLE storage");
    if (!model_get_string(m, "qwen4exp.ple.storage_dtype", &value) ||
        !ds4_streq(value, "BF16"))
        ds4_die("Qwen4Exp SSD-PLE reference artifact requires BF16 PLE storage");
    if (!model_get_string(m, "qwen4exp.ple.sidecar_manifest", &value) ||
        !ds4_streq(value, "ple/ple-manifest.json"))
        ds4_die("Qwen4Exp SSD-PLE has an unexpected sidecar manifest path");
    config_expect_bool("ple.resident_weight",
                       required_bool(m, "qwen4exp.ple.resident_weight"), false);
    config_expect_u64("ple.sidecar_payload_bytes",
                      required_u64_compat(m, "qwen4exp.ple.sidecar_payload_bytes"),
                      UINT64_C(102400491520));
    config_expect_u32("ple.sidecar_alignment",
                      required_u32(m, "qwen4exp.ple.sidecar_alignment"), 4096u);

    tensor_expect_layout(required_tensor(m, "blk.1.ple.layer_multipliers"),
                         DS4_TENSOR_I64, 1u, 3u, 0u, 0u);
    tensor_expect_layout(required_tensor(m, "blk.1.ple.head_offsets"),
                         DS4_TENSOR_I64, 1u, 16u, 0u, 0u);
    tensor_expect_layout(required_tensor(m, "blk.1.ple.head_vocab_sizes"),
                         DS4_TENSOR_I64, 1u, 16u, 0u, 0u);

    for (uint32_t part = 0; part < 128u; part++) {
        char name[96];
        int n = snprintf(name, sizeof(name),
                         "blk.1.ple.ngram_embd.part_%03u.weight", part);
        if (n < 0 || (size_t)n >= sizeof(name))
            ds4_die("Qwen4Exp PLE tensor name is too long");
        if (model_find_tensor(m, name)) {
            fprintf(stderr,
                    "ds4: SSD-PLE GGUF unexpectedly contains resident tensor %s\n",
                    name);
            exit(1);
        }
    }
    return true;
}

/* Strict metadata gate for the Qwen4Exp checkpoints this implementation
 * supports.  Hybrid-attention schedules, PLE hashing geometry, multimodal
 * topology, and source/license pins are semantic inputs, not advisory labels. */
static void config_validate_qwen4exp_model(const ds4_model *m) {
    g_ds4_shape = DS4_SHAPE_QWEN38_FLASH_NEXT;
    memset(g_ds4_compress_ratios, 0, sizeof(g_ds4_compress_ratios));

    config_expect_u32("block_count", required_u32(m, "qwen4exp.block_count"),
                      DS4_N_LAYER);
    config_expect_u64("context_length",
                      required_u64_compat(m, "qwen4exp.context_length"),
                      DS4_ROPE_ORIG_CTX);
    config_expect_u32("embedding_length",
                      required_u32(m, "qwen4exp.embedding_length"), DS4_N_EMBD);
    config_expect_u32("vocab_size", required_u32(m, "qwen4exp.vocab_size"),
                      DS4_N_VOCAB);
    config_expect_u32("feed_forward_length",
                      required_u32(m, "qwen4exp.feed_forward_length"), DS4_N_FF_EXP);
    config_expect_u32("attention.head_count",
                      required_u32(m, "qwen4exp.attention.head_count"), DS4_N_HEAD);
    config_expect_u32("attention.head_count_kv",
                      required_u32(m, "qwen4exp.attention.head_count_kv"), DS4_N_HEAD_KV);
    config_expect_u32("attention.key_length",
                      required_u32(m, "qwen4exp.attention.key_length"), DS4_N_HEAD_DIM);
    config_expect_u32("attention.value_length",
                      required_u32(m, "qwen4exp.attention.value_length"), DS4_N_VALUE_DIM);
    config_expect_u32("rope.dimension_count",
                      required_u32(m, "qwen4exp.rope.dimension_count"), DS4_N_ROT);
    config_expect_u32("expert_count", required_u32(m, "qwen4exp.expert_count"),
                      DS4_N_EXPERT);
    config_expect_u32("expert_used_count",
                      required_u32(m, "qwen4exp.expert_used_count"), DS4_N_EXPERT_USED);
    config_expect_u32("expert_feed_forward_length",
                      required_u32(m, "qwen4exp.expert_feed_forward_length"), DS4_N_FF_EXP);
    config_expect_u32("expert_shared_count",
                      required_u32(m, "qwen4exp.expert_shared_count"), DS4_N_EXPERT_SHARED);
    config_expect_u32("expert_shared_feed_forward_length",
                      required_u32(m, "qwen4exp.expert_shared_feed_forward_length"),
                      DS4_N_FF_SHEXP);
    config_expect_u32("nextn_predict_layers",
                      required_u32(m, "qwen4exp.nextn_predict_layers"), 1u);
    config_expect_u32("full_attention_interval",
                      required_u32(m, "qwen4exp.full_attention_interval"), 4u);
    config_expect_u32("attention.indexer.head_count",
                      required_u32(m, "qwen4exp.attention.indexer.head_count"),
                      DS4_N_INDEXER_HEAD);
    config_expect_u32("attention.indexer.key_length",
                      required_u32(m, "qwen4exp.attention.indexer.key_length"),
                      DS4_N_INDEXER_HEAD_DIM);
    config_expect_u32("attention.indexer.top_k",
                      required_u32(m, "qwen4exp.attention.indexer.top_k"),
                      DS4_N_INDEXER_TOP_K);

    config_expect_u32("attention.linear_key_head_count",
                      required_u32(m, "qwen4exp.attention.linear_key_head_count"), 16u);
    config_expect_u32("attention.linear_value_head_count",
                      required_u32(m, "qwen4exp.attention.linear_value_head_count"), 48u);
    config_expect_u32("attention.linear_key_length",
                      required_u32(m, "qwen4exp.attention.linear_key_length"), 128u);
    config_expect_u32("attention.linear_value_length",
                      required_u32(m, "qwen4exp.attention.linear_value_length"), 128u);
    config_expect_u32("attention.linear_conv_kernel",
                      required_u32(m, "qwen4exp.attention.linear_conv_kernel"), 4u);
    config_expect_u32("attention.indexer.compress_ratio",
                      required_u32(m, "qwen4exp.attention.indexer.compress_ratio"), 4u);
    config_expect_u32("attention.indexer.kv_head_count",
                      required_u32(m, "qwen4exp.attention.indexer.kv_head_count"), 1u);
    config_expect_u32("hyper_connection.count",
                      required_u32(m, "qwen4exp.hyper_connection.count"), DS4_N_HC);
    config_expect_u32("hyper_connection.lowrank",
                      required_u32(m, "qwen4exp.hyper_connection.lowrank"), 320u);
    config_expect_bool("rms_norm.zero_centered",
                       required_bool(m, "qwen4exp.rms_norm.zero_centered"), true);

    config_expect_u32("ple.ngram_size",
                      required_u32(m, "qwen4exp.ple.ngram_size"), 3u);
    config_expect_u32("ple.heads_per_ngram",
                      required_u32(m, "qwen4exp.ple.heads_per_ngram"), 8u);
    config_expect_u32("ple.ngram_vocab_size_base",
                      required_u32(m, "qwen4exp.ple.ngram_vocab_size_base"), 20000000u);
    config_expect_u32("ple.ngram_parts",
                      required_u32(m, "qwen4exp.ple.ngram_parts"), 128u);
    config_expect_u32("ple.embedding_length",
                      required_u32(m, "qwen4exp.ple.embedding_length"), DS4_N_EMBD);
    config_expect_u32("ple.conv_kernel",
                      required_u32(m, "qwen4exp.ple.conv_kernel"), 4u);
    (void)config_validate_qwen4exp_external_ple(m);
    config_expect_bool("mtp.present", required_bool(m, "qwen4exp.mtp.present"), true);
    config_expect_u32("mtp.block_count",
                      required_u32(m, "qwen4exp.mtp.block_count"), 1u);
    config_expect_bool("vision.present",
                       required_bool(m, "qwen4exp.vision.present"), true);
    config_expect_u32("vision.block_count",
                      required_u32(m, "qwen4exp.vision.block_count"), 27u);
    config_expect_u32("vision.embedding_length",
                      required_u32(m, "qwen4exp.vision.embedding_length"), 1152u);
    config_expect_u32("vision.feed_forward_length",
                      required_u32(m, "qwen4exp.vision.feed_forward_length"), 4304u);
    config_expect_u32("vision.head_count",
                      required_u32(m, "qwen4exp.vision.head_count"), 16u);
    config_expect_u32("vision.output_embedding_length",
                      required_u32(m, "qwen4exp.vision.output_embedding_length"), DS4_N_EMBD);
    config_expect_u32("vision.patch_size",
                      required_u32(m, "qwen4exp.vision.patch_size"), 16u);
    config_expect_u32("vision.temporal_patch_size",
                      required_u32(m, "qwen4exp.vision.temporal_patch_size"), 2u);
    config_expect_u32("vision.spatial_merge_size",
                      required_u32(m, "qwen4exp.vision.spatial_merge_size"), 2u);
    config_expect_u32("vision.position_count",
                      required_u32(m, "qwen4exp.vision.position_count"), 2304u);

    config_expect_f32("attention.layer_norm_rms_epsilon",
                      required_f32(m, "qwen4exp.attention.layer_norm_rms_epsilon"),
                      DS4_RMS_EPS);
    config_expect_f32("rope.freq_base",
                      required_f32(m, "qwen4exp.rope.freq_base"), DS4_ROPE_FREQ_BASE);

    ds4_str value = {0};
    if (!model_get_string(m, "qwen4exp.attention.output_gate_type", &value) ||
        !ds4_streq(value, "sigmoid"))
        ds4_die("Qwen4Exp requires sigmoid attention output gating");
    if (!model_get_string(m, "general.source.revision", &value) ||
        !qwen4exp_source_revision_supported(value))
        ds4_die("Qwen4Exp GGUF does not match the pinned source revision");
    if (!model_get_string(m, "qwen4exp.source.config_sha256", &value) ||
        !ds4_streq(value, "889658f2508e8c61d409b02e70e0d78d8d4452ec65aaafbe129805d213d2e74b"))
        ds4_die("Qwen4Exp GGUF does not match the pinned source config");
    if (!model_get_string(m, "qwen4exp.source.license_sha256", &value) ||
        !ds4_streq(value, "a0dc422560841fd68e06d974907f8b4c709bca44a67daad2b528437bdf676c08"))
        ds4_die("Qwen4Exp GGUF does not match the pinned Qwen Community License");
    if (!model_get_string(m, "general.license", &value) || !ds4_streq(value, "other"))
        ds4_die("Qwen4Exp GGUF has an incorrect general.license value");
    if (!model_get_string(m, "general.license.name", &value) ||
        !ds4_streq(value, "qwen-community-1.0"))
        ds4_die("Qwen4Exp GGUF has an incorrect license name");

    ds4_array_ref types = {0};
    if (!model_get_array(m, "qwen4exp.attention.layer_types", &types) ||
        types.type != GGUF_VALUE_STRING || types.len != DS4_N_LAYER)
        ds4_die("Qwen4Exp layer_types must contain 48 strings");
    ds4_cursor tc = cursor_at(m, types.data_pos);
    for (uint32_t il = 0; il < DS4_N_LAYER; il++) {
        ds4_str got = {0};
        if (!cursor_string(&tc, &got)) ds4_die(tc.error);
        const bool full = ds4_qwen4exp_layer_is_full_attention(il);
        if (!ds4_streq(got, full ? "full_attention" : "linear_attention")) {
            fprintf(stderr, "ds4: Qwen4Exp layer_types[%u] has the wrong branch\n", il);
            exit(1);
        }
    }

    ds4_array_ref full = {0};
    if (!model_get_array(m, "qwen4exp.attention.full_layers", &full) ||
        (full.type != GGUF_VALUE_UINT32 && full.type != GGUF_VALUE_INT32) ||
        full.len != DS4_N_FULL_ATTN_COUNT)
        ds4_die("Qwen4Exp full_layers must contain 12 integer indices");
    ds4_cursor fc = cursor_at(m, full.data_pos);
    for (uint32_t i = 0; i < DS4_N_FULL_ATTN_COUNT; i++) {
        uint32_t got = 0;
        if (full.type == GGUF_VALUE_UINT32) {
            if (!cursor_u32(&fc, &got)) ds4_die(fc.error);
        } else {
            int32_t signed_got = 0;
            if (!cursor_read(&fc, &signed_got, sizeof(signed_got)) || signed_got < 0)
                ds4_die("Qwen4Exp full_layers contains an invalid index");
            got = (uint32_t)signed_got;
        }
        config_expect_u32("attention.full_layers entry", got, 4u * i + 3u);
    }

    const char *ple_keys[] = {
        "qwen4exp.ple.layer_ids_one_based",
        "qwen4exp.ple.checkpoint_layer_ids_zero_based",
    };
    const uint32_t ple_want[] = {2u, 1u};
    for (uint32_t i = 0; i < 2u; i++) {
        ds4_array_ref arr = {0};
        if (!model_get_array(m, ple_keys[i], &arr) || arr.len != 1u ||
            (arr.type != GGUF_VALUE_UINT32 && arr.type != GGUF_VALUE_INT32))
            ds4_die("Qwen4Exp PLE layer metadata is malformed");
        ds4_cursor ac = cursor_at(m, arr.data_pos);
        uint32_t got = 0;
        if (arr.type == GGUF_VALUE_UINT32) {
            if (!cursor_u32(&ac, &got)) ds4_die(ac.error);
        } else {
            int32_t sg = 0;
            if (!cursor_read(&ac, &sg, sizeof(sg)) || sg < 0)
                ds4_die("Qwen4Exp PLE layer metadata contains an invalid index");
            got = (uint32_t)sg;
        }
        config_expect_u32(ple_keys[i], got, ple_want[i]);
    }
}

static void config_validate_model(const ds4_model *m) {
    ds4_str arch = {0};
    if (!model_get_string(m, "general.architecture", &arch) ||
        ds4_streq(arch, "deepseek4")) {
        config_validate_deepseek4_model(m);
        return;
    }
    if (ds4_streq(arch, "exaone-moe")) {
        config_validate_exaone_moe_model(m);
        return;
    }
    if (ds4_streq(arch, "solar-open2")) {
        config_validate_solar_open2_model(m);
        return;
    }
    if (ds4_streq(arch, "motif3")) {
        config_validate_motif3_model(m);
        return;
    }
    if (ds4_streq(arch, "dots3-note")) {
        config_validate_dots3_note_model(m);
        return;
    }
    if (ds4_streq(arch, "qwen4exp")) {
        config_validate_qwen4exp_model(m);
        return;
    }
    fprintf(stderr, "ds4: unsupported GGUF architecture: %.*s\n",
            (int)arch.len, arch.ptr);
    exit(1);
}

static void weights_bind_motif3_layer(
        ds4_layer_weights *l,
        const ds4_model   *m,
        uint32_t           il) {
    l->attn_norm = required_tensorf(m, "blk.%u.attn_norm.weight", il);
    l->mhc_attn_rms_norm = required_tensorf(m, "blk.%u.mhc_attn.rms_norm.weight", il);
    l->mhc_attn_proj_pre = required_tensorf(m, "blk.%u.mhc_attn.proj_pre.weight", il);
    l->mhc_attn_proj_post = required_tensorf(m, "blk.%u.mhc_attn.proj_post.weight", il);
    l->mhc_attn_proj_res = required_tensorf(m, "blk.%u.mhc_attn.proj_res.weight", il);
    l->mhc_attn_alpha_pre = required_tensorf(m, "blk.%u.mhc_attn.alpha_pre", il);
    l->mhc_attn_alpha_post = required_tensorf(m, "blk.%u.mhc_attn.alpha_post", il);
    l->mhc_attn_alpha_res = required_tensorf(m, "blk.%u.mhc_attn.alpha_res", il);
    l->mhc_attn_bias_pre = required_tensorf(m, "blk.%u.mhc_attn.bias_pre", il);
    l->mhc_attn_bias_post = required_tensorf(m, "blk.%u.mhc_attn.bias_post", il);
    l->mhc_attn_bias_res = required_tensorf(m, "blk.%u.mhc_attn.bias_res", il);

    l->attn_q_a = required_tensorf(m, "blk.%u.attn_q_a.weight", il);
    l->attn_q_a_norm = required_tensorf(m, "blk.%u.attn_q_a_norm.weight", il);
    l->attn_q_b = required_tensorf(m, "blk.%u.attn_q_b.weight", il);
    l->attn_q_gate = required_tensorf(m, "blk.%u.attn_q_gate.weight", il);
    l->attn_kv_a_mqa = required_tensorf(m, "blk.%u.attn_kv_a.weight", il);
    l->attn_kv_a_norm = required_tensorf(m, "blk.%u.attn_kv_a_norm.weight", il);
    l->attn_kv_b = required_tensorf(m, "blk.%u.attn_kv_b.weight", il);
    l->attn_lambda = required_tensorf(m, "blk.%u.attn_lambda.weight", il);
    l->attn_output = required_tensorf(m, "blk.%u.attn_output.weight", il);

    l->mhc_ffn_rms_norm = required_tensorf(m, "blk.%u.mhc_ffn.rms_norm.weight", il);
    l->mhc_ffn_proj_pre = required_tensorf(m, "blk.%u.mhc_ffn.proj_pre.weight", il);
    l->mhc_ffn_proj_post = required_tensorf(m, "blk.%u.mhc_ffn.proj_post.weight", il);
    l->mhc_ffn_proj_res = required_tensorf(m, "blk.%u.mhc_ffn.proj_res.weight", il);
    l->mhc_ffn_alpha_pre = required_tensorf(m, "blk.%u.mhc_ffn.alpha_pre", il);
    l->mhc_ffn_alpha_post = required_tensorf(m, "blk.%u.mhc_ffn.alpha_post", il);
    l->mhc_ffn_alpha_res = required_tensorf(m, "blk.%u.mhc_ffn.alpha_res", il);
    l->mhc_ffn_bias_pre = required_tensorf(m, "blk.%u.mhc_ffn.bias_pre", il);
    l->mhc_ffn_bias_post = required_tensorf(m, "blk.%u.mhc_ffn.bias_post", il);
    l->mhc_ffn_bias_res = required_tensorf(m, "blk.%u.mhc_ffn.bias_res", il);
    l->ffn_norm = required_tensorf(m, "blk.%u.ffn_norm.weight", il);

    if (il < DS4_N_LEADING_DENSE) {
        l->ffn_gate = required_tensorf(m, "blk.%u.ffn_gate.weight", il);
        l->ffn_up = required_tensorf(m, "blk.%u.ffn_up.weight", il);
        l->ffn_down = required_tensorf(m, "blk.%u.ffn_down.weight", il);
        l->ffn_polynorm_weight =
            required_tensorf(m, "blk.%u.ffn_polynorm.weight", il);
        l->ffn_polynorm_bias =
            required_tensorf(m, "blk.%u.ffn_polynorm.bias", il);
        return;
    }

    l->ffn_gate_inp = required_tensorf(m, "blk.%u.ffn_gate_inp.weight", il);
    l->ffn_exp_probs_b = required_tensorf(m, "blk.%u.exp_probs_b.bias", il);
    l->ffn_gate_exps = required_tensorf(m, "blk.%u.ffn_gate_exps.weight", il);
    l->ffn_up_exps = required_tensorf(m, "blk.%u.ffn_up_exps.weight", il);
    l->ffn_down_exps = required_tensorf(m, "blk.%u.ffn_down_exps.weight", il);
    l->ffn_polynorm_exps_weight =
        required_tensorf(m, "blk.%u.ffn_polynorm_exps.weight", il);
    l->ffn_polynorm_exps_bias =
        required_tensorf(m, "blk.%u.ffn_polynorm_exps.bias", il);
    l->ffn_gate_shexp = required_tensorf(m, "blk.%u.ffn_gate_shexp.weight", il);
    l->ffn_up_shexp = required_tensorf(m, "blk.%u.ffn_up_shexp.weight", il);
    l->ffn_down_shexp = required_tensorf(m, "blk.%u.ffn_down_shexp.weight", il);
    l->ffn_polynorm_shexp_weight =
        required_tensorf(m, "blk.%u.ffn_polynorm_shexp.weight", il);
    l->ffn_polynorm_shexp_bias =
        required_tensorf(m, "blk.%u.ffn_polynorm_shexp.bias", il);
}

/* K-EXAONE uses plain GQA with per-head Q/K RMSNorm and keeps its trailing
 * NextN block inside block_count. That trailing block is dense, unlike the
 * routed layers between the leading dense block and NextN. */
static void weights_bind_exaone_moe_layer(
        ds4_layer_weights *l,
        const ds4_model   *m,
        uint32_t           il) {
    l->attn_norm   = required_tensorf(m, "blk.%u.attn_norm.weight", il);
    l->attn_q      = required_tensorf(m, "blk.%u.attn_q.weight", il);
    l->attn_k      = required_tensorf(m, "blk.%u.attn_k.weight", il);
    l->attn_v      = required_tensorf(m, "blk.%u.attn_v.weight", il);
    l->attn_output = required_tensorf(m, "blk.%u.attn_output.weight", il);
    if (DS4_USE_QK_NORM) {
        l->attn_q_norm = required_tensorf(m, "blk.%u.attn_q_norm.weight", il);
        l->attn_k_norm = required_tensorf(m, "blk.%u.attn_k_norm.weight", il);
    }
    l->ffn_norm = required_tensorf(m, "blk.%u.ffn_norm.weight", il);

    const bool is_nextn = DS4_N_NEXTN_PREDICT != 0 &&
                          il + DS4_N_NEXTN_PREDICT >= DS4_N_LAYER;
    if (il < DS4_N_LEADING_DENSE || is_nextn) {
        l->ffn_gate = required_tensorf(m, "blk.%u.ffn_gate.weight", il);
        l->ffn_up   = required_tensorf(m, "blk.%u.ffn_up.weight", il);
        l->ffn_down = required_tensorf(m, "blk.%u.ffn_down.weight", il);
    } else {
        l->ffn_gate_inp    = required_tensorf(m, "blk.%u.ffn_gate_inp.weight", il);
        l->ffn_exp_probs_b = required_tensorf(m, "blk.%u.exp_probs_b.bias", il);
        l->ffn_gate_exps   = required_tensorf(m, "blk.%u.ffn_gate_exps.weight", il);
        l->ffn_up_exps     = required_tensorf(m, "blk.%u.ffn_up_exps.weight", il);
        l->ffn_down_exps   = required_tensorf(m, "blk.%u.ffn_down_exps.weight", il);
        l->ffn_gate_shexp  = required_tensorf(m, "blk.%u.ffn_gate_shexp.weight", il);
        l->ffn_up_shexp    = required_tensorf(m, "blk.%u.ffn_up_shexp.weight", il);
        l->ffn_down_shexp  = required_tensorf(m, "blk.%u.ffn_down_shexp.weight", il);
    }

    if (is_nextn) {
        l->nextn_eh_proj = required_tensorf(m, "blk.%u.nextn.eh_proj.weight", il);
        l->nextn_enorm   = required_tensorf(m, "blk.%u.nextn.enorm.weight", il);
        l->nextn_hnorm   = required_tensorf(m, "blk.%u.nextn.hnorm.weight", il);
        l->nextn_shared_head_norm =
            required_tensorf(m, "blk.%u.nextn.shared_head_norm.weight", il);
    }
}

