/* Native-session model families use the public session contract for scalar
 * generation.  This keeps CLI/embedding callers on the same graph and state
 * lifecycle as the server instead of entering DeepSeek's raw-SWA executor. */
static int generate_public_session_argmax(
        ds4_engine        *e,
        const ds4_tokens  *prompt,
        int                n_predict,
        int                ctx_size,
        ds4_token_emit_fn  emit,
        ds4_generation_done_fn done,
        void              *emit_ud,
        ds4_session_progress_fn progress,
        void              *progress_ud) {
    if (!e || !prompt || prompt->len <= 0 || ctx_size <= 0 ||
        prompt->len >= ctx_size) {
        fprintf(stderr, "ds4: prompt is empty or exceeds context size\n");
        return 1;
    }

    ds4_session *session = NULL;
    if (ds4_session_create(&session, e, ctx_size) != 0 || !session) {
        fprintf(stderr,
                "ds4: failed to create public-session generation runtime\n");
        return 1;
    }
    ds4_session_set_progress(session, progress, progress_ud);

    char err[256] = {0};
    const double prefill_t0 = now_sec();
    if (ds4_session_sync(session, prompt, err, sizeof(err)) != 0) {
        fprintf(stderr, "ds4: public-session prefill failed: %s\n",
                err[0] ? err : "unknown error");
        ds4_session_free(session);
        return 1;
    }
    const double prefill_t1 = now_sec();

    const bool trace_top = getenv("DS4_TRACE_TOP") != NULL;
    const bool token_trace = getenv("DS4_TOKEN_TRACE") != NULL;
    const bool token_timing = getenv("DS4_TOKEN_TIMING") != NULL;
    float *trace_logits = trace_top
        ? xmalloc((size_t)DS4_N_VOCAB * sizeof(float)) : NULL;
    const int eos = ds4_token_eos(e);
    int pos = prompt->len;
    int n_generated = 0;
    int n_decode_eval = 0;
    int rc = 0;
    const double decode_t0 = now_sec();
    for (int i = 0; i < n_predict && pos < ctx_size; i++) {
        if (trace_top) {
            if (ds4_session_copy_logits(
                    session, trace_logits, DS4_N_VOCAB) !=
                (int)DS4_N_VOCAB) {
                fprintf(stderr,
                        "ds4: failed to read public-session trace logits\n");
                rc = 1;
                break;
            }
            char label[64];
            snprintf(label, sizeof(label), "step %d", i);
            print_top_logits(stderr, label, &e->vocab,
                             trace_logits, DS4_N_VOCAB, 10);
        }

        const int token = ds4_session_argmax(session);
        if (token < 0) {
            fprintf(stderr, "ds4: public-session argmax failed\n");
            rc = 1;
            break;
        }
        if (token == eos || ds4_token_is_stop(e, token)) break;
        if (emit) emit(emit_ud, token);
        if (token_trace) {
            fprintf(stderr,
                    "ds4: token trace generated=%d pos=%d token=%d\n",
                    n_generated, pos, token);
        }
        n_generated++;

        if (i == n_predict - 1 || pos + 1 >= ctx_size) {
            pos++;
            break;
        }
        const double eval_t0 = token_timing ? now_sec() : 0.0;
        err[0] = '\0';
        if (ds4_session_eval(session, token, err, sizeof(err)) != 0) {
            fprintf(stderr, "ds4: public-session decode failed: %s\n",
                    err[0] ? err : "unknown error");
            rc = 1;
            break;
        }
        if (token_timing) {
            fprintf(stderr, "ds4: gpu decode eval %d took %.3f ms\n",
                    n_decode_eval + 1, (now_sec() - eval_t0) * 1000.0);
        }
        n_decode_eval++;
        pos++;
    }
    const double decode_t1 = now_sec();
    if (done) done(emit_ud);

    const double prefill_s = prefill_t1 - prefill_t0;
    const double decode_s = decode_t1 - decode_t0;
    ds4_log(stderr,
            DS4_LOG_TIMING,
            "ds4: prefill: %.2f t/s, generation: %.2f t/s\n",
            prefill_s > 0.0 ? (double)prompt->len / prefill_s : 0.0,
            decode_s > 0.0 ? (double)n_generated / decode_s : 0.0);

    free(trace_logits);
    ds4_session_free(session);
    return rc;
}

/* memgov D4-2: typed reclaim status names for logs and counters (both
 * build shapes; fixed vocabulary -- extend the enum and this together). */
const char *ds4_reclaim_status_str(int status) {
    switch (status) {
    case DS4_RECLAIM_OK:           return "ok";
    case DS4_RECLAIM_PARTIAL:      return "partial";
    case DS4_RECLAIM_STALE_PLAN:   return "stale_plan";
    case DS4_RECLAIM_BUSY:         return "busy";
    case DS4_RECLAIM_UNSUPPORTED:  return "unsupported";
    case DS4_RECLAIM_DEVICE_ERROR: return "device_error";
    default:                       return "unknown";
    }
}

int ds4_engine_generate_argmax(
        ds4_engine        *e,
        const ds4_tokens  *prompt,
        int                n_predict,
        int                ctx_size,
        ds4_token_emit_fn  emit,
        ds4_generation_done_fn done,
        void              *emit_ud,
        ds4_session_progress_fn progress,
        void              *progress_ud) {
    if (DS4_MODEL_FAMILY == DS4_MODEL_FAMILY_SOLAR_OPEN2 ||
        DS4_MODEL_FAMILY == DS4_MODEL_FAMILY_MOTIF3 ||
        DS4_MODEL_FAMILY == DS4_MODEL_FAMILY_EXAONE_MOE) {
        return generate_public_session_argmax(
            e, prompt, n_predict, ctx_size, emit, done, emit_ud,
            progress, progress_ud);
    }
    const ds4_model *model = &e->model;
    const ds4_vocab *vocab = &e->vocab;
    const ds4_weights *weights = &e->weights;

    if (ds4_backend_uses_graph(e->backend)) {
#ifndef DS4_NO_GPU
        if (!e->metal_ready) {
            fprintf(stderr, "ds4: %s generation requested but the graph backend is unavailable\n",
                    ds4_backend_name(e->backend));
            return 1;
        }
        return generate_metal_graph_raw_swa(model, vocab, weights, prompt,
                                            n_predict, ctx_size, e->quality,
                                            e->power_percent,
                                            e->directional_steering_file,
                                            e->directional_steering_attn_scale,
                                            e->directional_steering_ffn_scale,
                                            emit, done, emit_ud,
                                            progress, progress_ud);
#else
        fprintf(stderr, "ds4: %s generation requested but this build has no graph backend support\n",
                ds4_backend_name(e->backend));
        return 1;
#endif
    }

    return generate_raw_swa_cpu(model, vocab, weights, prompt, n_predict,
                                ctx_size,
                                e->directional_steering_dirs,
                                e->directional_steering_attn_scale,
                                e->directional_steering_ffn_scale,
                                emit, done, emit_ud, progress, progress_ud);
}

int ds4_engine_metal_graph_test(ds4_engine *e, const ds4_tokens *prompt) {
#ifndef DS4_NO_GPU
    if (!e || DS4_MODEL_FAMILY != DS4_MODEL_FAMILY_DEEPSEEK4) {
        fprintf(stderr,
                "ds4: DeepSeek graph diagnostic is unavailable for this model family\n");
        return 1;
    }
    if (!e->metal_ready) {
        fprintf(stderr, "ds4: Metal graph test requested but Metal is unavailable\n");
        return 1;
    }
    return metal_graph_decode_test(&e->model, &e->weights, prompt);
#else
    (void)e;
    (void)prompt;
    fprintf(stderr, "ds4: Metal graph test requested but this build has no Metal support\n");
    return 1;
#endif
}

